  if(req.method==='DELETE'&&inventoryLotMatch){try{const i=await parseBody(req),lotId=Number(inventoryLotMatch[1]),reason=required(i.reason,'削除理由');const result=transaction(()=>{const lot=one('SELECT * FROM inventory_lots WHERE id=?',lotId),opening=one('SELECT * FROM inventory_opening_entries WHERE inventory_lot_id=?',lotId);if(!lot)throw new Error('在庫ロットがありません');if(!opening)throw new Error('削除できるのは在庫初期登録から作成したロットだけです');const unrelated=one("SELECT COUNT(*) count FROM inventory_movements WHERE lot_id=? AND (source_type<>'inventory_opening_entry' OR source_id<>?)",lotId,opening.id).count;const references=[['process_runs','input_lot_id'],['individual_process_results','input_lot_id'],['production_consumptions','inventory_lot_id'],['production_outputs','inventory_lot_id'],['delivery_preparation_materials','inventory_lot_id'],['shipment_lines','inventory_lot_id'],['stocktake_lines','lot_id']].reduce((sum,[table,column])=>sum+Number(one(`SELECT COUNT(*) count FROM ${table} WHERE ${column}=?`,lotId).count),0);const costs=Number(one('SELECT COUNT(*) count FROM inventory_lot_cost_components WHERE inventory_lot_id=?',lotId).count);if(Number(unrelated)>0||references>0||costs>0)throw new Error('使用履歴があるため削除できません。数量修正で0にしてください');audit(user,'DELETE','inventory_lot',lotId,{lot_no:lot.lot_no,opening_entry_id:opening.id,reason});db.prepare("DELETE FROM inventory_movements WHERE lot_id=? AND source_type='inventory_opening_entry' AND source_id=?").run(lotId,opening.id);db.prepare('DELETE FROM inventory_opening_entries WHERE id=?').run(opening.id);db.prepare('DELETE FROM inventory_lots WHERE id=?').run(lotId);return {deleted:true,lot_id:lotId};});return json(res,200,result);}catch(error){return fail(res,error);}}
  if(req.method==='POST'&&url.pathname==='/api/v1/inventory/opening-balances'){try{const i=await parseBody(req);const result=transaction(()=>{const item=one("SELECT * FROM inventory_items WHERE id=? AND active=1 AND item_type IN ('raw','packaging','flavor')",required(i.item_id,'品目'));if(!item)throw new Error('在庫初期登録できる品目は原料・包材・フレーバーです');const quantity=i.quantity==null||i.quantity===''?null:nonnegative(i.quantity,'数量'),enteredUnitCost=i.unit_cost==null||i.unit_cost===''?null:nonnegative(i.unit_cost,'単価'),enteredAmount=i.amount==null||i.amount===''?null:nonnegative(i.amount,'金額');if(quantity==null&&enteredUnitCost==null&&enteredAmount==null)throw new Error('数量・単価・金額のいずれかを入力してください');const amount=enteredAmount??(quantity!=null&&enteredUnitCost!=null?Math.round(quantity*enteredUnitCost):null),unitCost=enteredUnitCost??(quantity>0&&amount!=null?amount/quantity:0),registeredAt=new Date().toISOString().slice(0,10),sequence=Number(one('SELECT COALESCE(MAX(id),0)+1 next FROM inventory_opening_entries').next),lotNo=`OPEN-${registeredAt.replaceAll('-','')}-${sequence}`,lotId=getOrCreateLot(item.id,lotNo,registeredAt,unitCost??0);const id=Number(db.prepare('INSERT INTO inventory_opening_entries(item_id,inventory_lot_id,quantity,unit_cost,amount,memo,registered_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?)').run(item.id,lotId,quantity,enteredUnitCost,amount,i.memo??'',registeredAt,user.id,now()).lastInsertRowid);if(quantity>0)inventoryMove({lotId,date:registeredAt,type:'opening_balance',qty:quantity,sourceType:'inventory_opening_entry',sourceId:id,departmentId:item.department_id,memo:i.memo??''});audit(user,'CREATE','inventory_opening_entry',id,{item_id:item.id,quantity,unit_cost:enteredUnitCost,amount});return {id,lot_id:lotId,lot_no:lotNo,quantity,unit_cost:enteredUnitCost,amount};});return json(res,201,result);}catch(error){return fail(res,error);}}
