  if(req.method==='GET'&&url.pathname==='/api/v1/receivables')return json(res,200,{receivables:rows(`SELECT r.*,p.name partner_name FROM receivables r JOIN partners p ON p.id=r.partner_id WHERE (? IS NULL OR r.status=?) ORDER BY r.due_date`,url.searchParams.get('status'),url.searchParams.get('status'))});
  if(req.method==='GET'&&url.pathname==='/api/v1/payables')return json(res,200,{payables:rows(`SELECT py.*,p.name partner_name,i.name item_name,rl.lot_no FROM payables py JOIN partners p ON p.id=py.partner_id JOIN purchase_cost_entries pc ON pc.id=py.purchase_cost_entry_id JOIN receipt_lines rl ON rl.id=pc.receipt_line_id JOIN inventory_items i ON i.id=rl.item_id WHERE (? IS NULL OR py.status=?) ORDER BY py.due_date`,url.searchParams.get('status'),url.searchParams.get('status'))});
