function staticFile(res,url){let path=url.pathname==='/'?'/index.html':url.pathname;path=normalize(path).replace(/^(\.\.[/\\])+/, '');const file=resolve(root,'public',`.${path}`);if(!file.startsWith(resolve(root,'public'))||!existsSync(file)){res.writeHead(404);return res.end('Not found');}res.writeHead(200,{'content-type':mime[extname(file)]??'application/octet-stream','x-content-type-options':'nosniff'});res.end(readFileSync(file));}
export const server=http.createServer(async(req,res)=>{const url=new URL(req.url,`http://${req.headers.host??'localhost'}`);try{res.setHeader('x-frame-options','DENY');res.setHeader('referrer-policy','same-origin');if(url.pathname==='/healthz'){db.prepare('SELECT 1').get();return json(res,200,{ok:true});}if(url.pathname.startsWith('/api/'))await api(req,res,url);else staticFile(res,url);}catch(error){console.error(error);if(!res.headersSent)fail(res,error,500);else res.end();}});
